#!/usr/bin/env bun
/**
 * sync-docs.mjs — the content pipeline for the kutto_kodalo documentation site.
 *
 * `docs/` in the repository root is GENERATED by `bin/shellrc-doc` from the
 * `# @tag` doc blocks above each shell function. This script consumes that
 * output and never forks it: everything it writes under `src/content/docs/`
 * and `src/data/` is wiped and rebuilt on every run, and both directories are
 * gitignored. If a doc block changes, run `just docs` then rebuild the site.
 *
 *   ../docs/INDEX.md            -> src/content/docs/reference/index.md   (full index)
 *                               -> src/data/modules.json                 (landing page grid)
 *   ../docs/reference/<mod>.md  -> src/content/docs/reference/<mod>.md
 *   ../docs/CONVENTIONS.md      -> src/content/docs/conventions.md
 *   ../docs/functions.json      -> src/data/functions.json               (function browser)
 *
 * Node builtins only — no dependencies.
 *
 * Environment:
 *   SITE_GITHUB_REPO    owner/name for source links   (default thapakazi/kutto_kodalo)
 *   SITE_GITHUB_BRANCH  branch for source links       (default gumantae)
 *   SITE_BASE           path prefix of the deployment (default /kutto_kodalo)
 */

import { mkdir, readFile, readdir, rm, writeFile } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const SITE_DIR = path.resolve(fileURLToPath(new URL('..', import.meta.url)));
const REPO_DIR = path.resolve(SITE_DIR, '..');
const DOCS_DIR = path.join(REPO_DIR, 'docs');
const CONTENT_DIR = path.join(SITE_DIR, 'src', 'content', 'docs');
const DATA_DIR = path.join(SITE_DIR, 'src', 'data');

const GITHUB_REPO = process.env.SITE_GITHUB_REPO || 'thapakazi/kutto_kodalo';
const GITHUB_BRANCH = process.env.SITE_GITHUB_BRANCH || 'gumantae';
const BASE = withTrailingSlash(process.env.SITE_BASE ?? '/kutto_kodalo');

/** GitHub blob URL for a repo-relative path, e.g. `lib/00-core.sh`. */
const blobUrl = (file, fragment = '') =>
    `https://github.com/${GITHUB_REPO}/blob/${GITHUB_BRANCH}/${file}${fragment}`;

/** Site URL for a base-relative path, e.g. `reference/aws/`. */
const siteUrl = (p) => `${BASE}${p.replace(/^\/+/, '')}`;

function withTrailingSlash(p) {
    if (!p || p === '/') return '/';
    return p.endsWith('/') ? p : `${p}/`;
}

// ----------------------------------------------------------------- rewriting

/** Drop the generator's `<!-- DO NOT EDIT ... -->` banner. */
function stripBanner(md) {
    return md.replace(/^<!--\s*DO NOT EDIT[\s\S]*?-->\n+/i, '');
}

/**
 * `[`lib/00-core.sh:11`](../../lib/00-core.sh#L11)` is a link that only works
 * from inside a checkout. On a website it has to point at GitHub.
 */
function rewriteSourceLinks(md) {
    return md.replace(/\]\(\.\.\/\.\.\/([^)#\s]+)(#L\d+)?\)/g, (_m, file, frag) =>
        `](${blobUrl(file, frag || '')})`
    );
}

/** Links that INDEX.md makes to its siblings inside `docs/`. */
function rewriteDocLinks(md) {
    return md
        .replace(/\]\(reference\/([a-z0-9._-]+)\.md(#[^)]*)?\)/gi, (_m, mod, frag) =>
            `](${siteUrl(`reference/${mod}/`)}${frag || ''})`
        )
        .replace(/\]\(CONVENTIONS\.md\)/g, `](${siteUrl('conventions/')})`)
        .replace(/\]\(functions\.json\)/g, `](${blobUrl('docs/functions.json')})`)
        .replace(/\]\(INDEX\.md\)/g, `](${siteUrl('reference/')})`);
}

/** `> **⚠ DANGER** — text` reads better as a Starlight aside. */
function rewriteDanger(md) {
    return md.replace(/^> \*\*⚠ DANGER\*\* — (.*)$/gm, (_m, text) =>
        `:::danger[Destructive]\n${text}\n:::`
    );
}

/** A YAML double-quoted scalar. JSON string escaping is a valid subset. */
const yamlString = (s) => JSON.stringify(String(s));

/** One line, collapsed whitespace, no markdown ticks, capped length. */
function summarise(text, max = 155) {
    const flat = String(text).replace(/\s+/g, ' ').replace(/`/g, '').trim();
    if (flat.length <= max) return flat;
    return `${flat.slice(0, max - 1).replace(/[\s,;:.-]+$/, '')}…`;
}

// -------------------------------------------------------------- module pages

/**
 * A generated module page looks like:
 *
 *   <!-- DO NOT EDIT ... -->
 *   # aws
 *   <summary paragraph>
 *   ---
 *   ## `fn` ... (many)
 *   ---
 *   _26 functions. Source: `modules/common/aws.sh`. Generated by `bin/shellrc-doc`._
 */
function transformModulePage(module, raw) {
    let md = stripBanner(raw).trimEnd();

    // Title + summary come out of the body and into the frontmatter, because
    // Starlight renders the page title itself.
    md = md.replace(/^# .*\n+/, '');

    let summary = '';
    const summaryMatch = md.match(/^([^\n#][^\n]*(?:\n(?!\n|---)[^\n]*)*)\n\n/);
    if (summaryMatch && !summaryMatch[1].startsWith('---')) {
        summary = summaryMatch[1].replace(/\s+/g, ' ').trim();
        md = md.slice(summaryMatch[0].length);
    }

    // Source files are listed in the generated footer. Lift them to the top as
    // "this page came from there", and rewrite the footer itself.
    let sources = [];
    md = md.replace(
        /\n?---\n+_(\d+) functions?\. Source: (.+?)\. Generated by `bin\/shellrc-doc`\._\s*$/,
        (_m, count, sourceList) => {
            sources = [...sourceList.matchAll(/`([^`]+)`/g)].map((m2) => m2[1]);
            const links = sources.map((f) => `[\`${f}\`](${blobUrl(f)})`).join(', ');
            return `\n---\n\n_${count} function${count === '1' ? '' : 's'}. Source: ${links}._\n`;
        }
    );

    md = rewriteDanger(rewriteSourceLinks(md));

    const sourceLinks = sources.length
        ? sources.map((f) => `[\`${f}\`](${blobUrl(f)})`).join(', ')
        : `[the repository](${blobUrl('')})`;

    const frontmatter = [
        '---',
        `title: ${yamlString(module)}`,
        `description: ${yamlString(summary ? summarise(summary) : `The ${module} module of kutto_kodalo.`)}`,
        '---',
        '',
    ].join('\n');

    const lead = summary ? `${summary}\n\n` : '';
    const note =
        `:::note[Generated from source]\n` +
        `Every entry below is built from the \`# @describe\` / \`# @usage\` doc blocks in ` +
        `${sourceLinks}. Change the doc block above the function and run \`just docs\` — ` +
        `this page is never edited by hand.\n:::\n\n`;

    return `${frontmatter}\n${lead}${note}${md.trimStart()}\n`;
}

// ---------------------------------------------------------------- the index

/** Parse `## [mod](reference/mod.md)` sections out of docs/INDEX.md. */
function parseIndex(raw) {
    const totals = raw.match(/\*\*(\d+) functions? across (\d+) modules?\.\*\*/);
    const modules = [];
    const sectionRe = /^## \[([^\]]+)\]\(reference\/[^)]+\)\n\n([\s\S]*?)(?=\n## \[|\n*$)/gm;

    for (const match of raw.matchAll(sectionRe)) {
        const [, name, body] = match;
        const lines = body.split('\n');
        const firstBullet = lines.findIndex((line) => line.startsWith('- ['));
        const summaryLines = firstBullet === -1 ? lines : lines.slice(0, firstBullet);
        const summary = summaryLines.join(' ').replace(/\s+/g, ' ').trim();
        const count = lines.filter((line) => line.startsWith('- [')).length;
        modules.push({ name, summary, count });
    }

    return {
        functions: totals ? Number(totals[1]) : 0,
        modules: totals ? Number(totals[2]) : modules.length,
        list: modules,
    };
}

function transformIndexPage(raw) {
    let md = stripBanner(raw).trimEnd();

    md = md.replace(/^#\s+Function index\s*\n+/, '');
    // The generator's "do not edit this file by hand" paragraph is addressed to
    // someone with a checkout, not to a reader of the website.
    md = md.replace(
        /^This file is generated by[\s\S]*?run `just docs`\.\n\n/m,
        ''
    );

    md = rewriteDocLinks(md);

    const frontmatter = [
        '---',
        'title: All functions',
        'description: "Every kutto_kodalo function, grouped by module, one line each."',
        'sidebar:',
        '  order: 0',
        '  label: All functions',
        'tableOfContents:',
        '  minHeadingLevel: 2',
        '  maxHeadingLevel: 2',
        '---',
        '',
    ].join('\n');

    const note =
        `:::note[Generated from source]\n` +
        `This index is produced by [\`bin/shellrc-doc\`](${blobUrl('bin/shellrc-doc')}) from the ` +
        `doc blocks in \`lib/\` and \`modules/\`. Looking for something specific? The ` +
        `[function browser](${siteUrl('functions/')}) filters all of it as you type.\n:::\n\n`;

    return `${frontmatter}\n${note}${md.trimStart()}\n`;
}

function transformConventions(raw) {
    const md = rewriteDocLinks(stripBanner(raw))
        .replace(/^#\s+Conventions\s*\n+/, '')
        .trimStart();

    const frontmatter = [
        '---',
        'title: Conventions',
        'description: "The rules every kutto_kodalo module follows: doc blocks, naming, portability, safety."',
        '---',
        '',
    ].join('\n');

    const note =
        `:::tip[Hand-written]\n` +
        `This is the only page in the documentation that is *not* generated. ` +
        `Source: [\`docs/CONVENTIONS.md\`](${blobUrl('docs/CONVENTIONS.md')}).\n:::\n\n`;

    return `${frontmatter}\n${note}${md}\n`;
}

// --------------------------------------------------------------------- main

async function main() {
    // Everything below these two directories is derived. Start from nothing so
    // a removed module can never linger as a stale page.
    await rm(CONTENT_DIR, { recursive: true, force: true });
    await rm(DATA_DIR, { recursive: true, force: true });
    await mkdir(path.join(CONTENT_DIR, 'reference'), { recursive: true });
    await mkdir(DATA_DIR, { recursive: true });

    const indexRaw = await readFile(path.join(DOCS_DIR, 'INDEX.md'), 'utf8');
    const parsed = parseIndex(indexRaw);

    await writeFile(
        path.join(CONTENT_DIR, 'reference', 'index.md'),
        transformIndexPage(indexRaw)
    );

    const conventionsRaw = await readFile(path.join(DOCS_DIR, 'CONVENTIONS.md'), 'utf8');
    await writeFile(path.join(CONTENT_DIR, 'conventions.md'), transformConventions(conventionsRaw));

    const referenceDir = path.join(DOCS_DIR, 'reference');
    const files = (await readdir(referenceDir)).filter((f) => f.endsWith('.md')).sort();
    for (const file of files) {
        const module = path.basename(file, '.md');
        const raw = await readFile(path.join(referenceDir, file), 'utf8');
        await writeFile(
            path.join(CONTENT_DIR, 'reference', file),
            transformModulePage(module, raw)
        );
    }

    // functions.json is copied rather than imported across the project root so
    // that Vite never has to serve a file outside `site/`.
    const functionsRaw = await readFile(path.join(DOCS_DIR, 'functions.json'), 'utf8');
    const functions = JSON.parse(functionsRaw);
    await writeFile(path.join(DATA_DIR, 'functions.json'), functionsRaw);

    // Module names and summaries come from INDEX.md (which is what a reader of
    // the repo sees); the counts come from functions.json so that the landing
    // page can never disagree with the function browser.
    const modulesByName = new Map(parsed.list.map((m) => [m.name, { ...m, count: 0 }]));
    for (const fn of functions) {
        if (!modulesByName.has(fn.module)) {
            modulesByName.set(fn.module, {
                name: fn.module,
                summary: fn.module_summary || '',
                count: 0,
            });
        }
        const entry = modulesByName.get(fn.module);
        entry.count += 1;
        entry.os ??= new Set();
        entry.os.add(fn.os || 'any');
        if (fn.danger) entry.danger = (entry.danger || 0) + 1;
    }
    const modules = [...modulesByName.values()].sort((a, b) => a.name.localeCompare(b.name));

    await writeFile(
        path.join(DATA_DIR, 'modules.json'),
        `${JSON.stringify(
            {
                totals: { functions: functions.length, modules: modules.length },
                repo: GITHUB_REPO,
                branch: GITHUB_BRANCH,
                modules: modules.map((m) => ({
                    name: m.name,
                    summary: m.summary,
                    count: m.count,
                    os: [...(m.os ?? ['any'])].sort(),
                    danger: m.danger ?? 0,
                })),
            },
            null,
            2
        )}\n`
    );

    process.stdout.write(
        `sync-docs: ${files.length} module pages, ${functions.length} functions -> src/content/docs/ ` +
        `(base ${BASE}, source links -> ${GITHUB_REPO}@${GITHUB_BRANCH})\n`
    );
}

main().catch((error) => {
    process.stderr.write(`sync-docs: ${error.stack || error}\n`);
    process.exitCode = 1;
});
